import{_ as o,o as i,c as t,aa as a}from"./chunks/framework.BAs_AphD.js";const h=JSON.parse('{"title":"Cookies in the Buildary.online Application","description":"","frontmatter":{"title":"Cookies in the Buildary.online Application","wiki":"en:diary:cookies"},"headers":[],"relativePath":"en/diary/cookies.md","filePath":"en/diary/cookies.md","lastUpdated":1793088561000}'),n={name:"en/diary/cookies.md"};function s(r,e,c,l,d,u){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="cookies-in-the-buildary-online-application" tabindex="-1">Cookies in the Buildary.online Application <a class="header-anchor" href="#cookies-in-the-buildary-online-application" aria-label="Permalink to &quot;Cookies in the Buildary.online Application&quot;">​</a></h1><p>Like most websites, the Buildary.online application also uses cookies.</p><p>&quot;Cookies&quot; are pieces of information that are transferred from a website to the user&#39;s computer hard drive. Cookies allow a website to remember important information, making it easier for the user to use the website in the future.</p><p>The application uses technical cookies that are necessary to ensure the proper operation of the services.</p><ul><li>If the application is operated on the customer&#39;s infrastructure in an on-premise environment, such as the ČEZ Group, technical cookies are the only cookies used by the application.</li><li>If the application is operated as a publicly accessible service, the application also uses cookies from Google Analytics, which are used to create anonymous statistics about user access.</li></ul><p>The application does not collect or transmit any personal information about users and is fully compliant with GDPR requirements. Detailed information about personal data protection policies is provided in the General Terms and Conditions or in individual agreements concluded with individual customers.</p><p>Below is a list of cookies used by the respective services:</p><ul><li>.AuthScheme – contains the name of the authentication scheme when logging in using a third-party ID server</li><li>.idsrv.session – allows changes to the session to be detected and contains the session identifier</li><li>.AspNetCore.Identity.Application – authorization cookie used when renewing the user&#39;s token</li></ul><h2 id="account-deletion" tabindex="-1">Account Deletion <a class="header-anchor" href="#account-deletion" aria-label="Permalink to &quot;Account Deletion&quot;">​</a></h2><p>If you decide to stop using Buildary completely and delete your account, please contact us at <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a> to request its deletion.</p><h2 id="cookies-in-the-esd-system-for-cezd" tabindex="-1">Cookies in the ESD System for ČEZd <a class="header-anchor" href="#cookies-in-the-esd-system-for-cezd" aria-label="Permalink to &quot;Cookies in the ESD System for ČEZd&quot;">​</a></h2><p>For more information, see <a href="https://www.cezdistribuce.cz/cs/informace-o-webu/cookies" target="_blank" rel="noreferrer">HERE</a>.</p><h2 id="account-deletion-for-cezd" tabindex="-1">Account Deletion for ČEZd <a class="header-anchor" href="#account-deletion-for-cezd" aria-label="Permalink to &quot;Account Deletion for ČEZd&quot;">​</a></h2><p>If you decide to stop using ESD completely and delete your account, please contact the ČEZ Group helpdesk.</p>',14)])])}const f=o(n,[["render",s]]);export{h as __pageData,f as default};
